To print the contents of the `rxdataF` variable in C, you need to iterate through its elements and print each one. The `rxdataF` variable is a 2D array of `int32_t` values, so you'll need to loop through both dimensions.

Here's a function that prints the contents of `rxdataF`. This assumes that `ru->nb_rx` specifies the number of receivers, and you have access to `NUMBER_RX_BUFFERS`, `fp->symbols_per_slot`, and `fp->ofdm_symbol_size` to determine the dimensions of the inner arrays.

```c
#include <stdio.h>
#include <stdint.h>

// Assuming the following structures and macros are defined somewhere in your code
#define NUMBER_RX_BUFFERS 10 // example value

typedef struct {
    int32_t **rxdataF;
} Common;

typedef struct {
    Common common;
    int nb_rx;
} RU;

typedef struct {
    int symbols_per_slot;
    int ofdm_symbol_size;
} FrameParms;

void printRxdataF(RU *ru, FrameParms *fp) {
    for (int i = 0; i < ru->nb_rx; i++) {
        printf("Receiver %d:\n", i);
        for (int j = 0; j < NUMBER_RX_BUFFERS * fp->symbols_per_slot * fp->ofdm_symbol_size; j++) {
            printf("%d ", ru->common.rxdataF[i][j]);
            // Optional: format output for readability
            if ((j + 1) % fp->ofdm_symbol_size == 0) {
                printf("\n");
            }
        }
        printf("\n"); // Separate receivers
    }
}

int main() {
    // Example initialization
    RU ru;
    FrameParms fp = {14, 1024}; // example values for symbols_per_slot and ofdm_symbol_size
    ru.nb_rx = 2; // example value

    // Allocate memory for rxdataF
    ru.common.rxdataF = (int32_t**)malloc(ru.nb_rx * sizeof(int32_t*));
    for (int i = 0; i < ru.nb_rx; i++) {
        ru.common.rxdataF[i] = (int32_t*)malloc(NUMBER_RX_BUFFERS * fp.symbols_per_slot * fp.ofdm_symbol_size * sizeof(int32_t));
        // Initialize with example data
        for (int j = 0; j < NUMBER_RX_BUFFERS * fp.symbols_per_slot * fp.ofdm_symbol_size; j++) {
            ru.common.rxdataF[i][j] = j; // example data
        }
    }

    // Print rxdataF
    printRxdataF(&ru, &fp);

    // Free allocated memory
    for (int i = 0; i < ru.nb_rx; i++) {
        free(ru.common.rxdataF[i]);
    }
    free(ru.common.rxdataF);

    return 0;
}
```

### Explanation:
- **Structure Definitions**: Assumes `RU` and `FrameParms` structures and `NUMBER_RX_BUFFERS` macro are defined.
