    <script src="https://cdn.jsdelivr.net/npm/@xenova/transformers@1.1.0"></script>
    <script src="app.js"></script>
</body>
</html>
```

#### 4. Implement JavaScript Logic

Create an `app.js` file and write JavaScript code to handle the chat interactions:

```javascript
// Load the BlenderBot model
const model = await transformers.load("Xenova/blenderbot-400M-distill");

document.getElementById('send-button').addEventListener('click', async () => {
    const userInput = document.getElementById('user-input').value;
    if (!userInput) return;

    // Display user message
    displayMessage(userInput, 'user');

    // Get the bot's response
    const response = await model.chat(userInput);

    // Display bot message
    displayMessage(response, 'bot');

    // Clear input
    document.getElementById('user-input').value = '';
});

function displayMessage(message, sender) {
    const chatBox = document.getElementById('chat-box');
    const messageElement = document.createElement('div');
    messageElement.textContent = `${sender.toUpperCase()}: ${message}`;
    chatBox.appendChild(messageElement);
    chatBox.scrollTop = chatBox.scrollHeight;
}
```

### Explanation

