    override fun onStartCommand(intent: android.content.Intent?, flags: Int, startId: Int): Int {
        vpnThread = Thread(Runnable {
            try {
                runVpn()
            } catch (e: Exception) {
                e.printStackTrace()
            }
        }, "MyVpnThread")

        vpnThread?.start()
        return START_STICKY
    }

    private fun runVpn() {
        // Configure a builder for the VPN interface.
        val builder = Builder()

        // Configure VPN with basic parameters.
        builder.addAddress("10.0.0.2", 24)
        builder.addRoute("0.0.0.0", 0)
        builder.setSession("MyVPNService")
        builder.setMtu(1500)

        // Establish the VPN interface.
        vpnInterface = builder.establish()

        // Open a DatagramChannel to handle communication.
        val datagramChannel = DatagramChannel.open()
        datagramChannel.connect(InetSocketAddress("8.8.8.8", 53)) // Example to connect to Google's DNS
        datagramChannel.configureBlocking(false)

        // Allocate the buffer for packet processing.
        val packetBuffer = ByteBuffer.allocate(32767)

        while (!Thread.interrupted()) {
            // Clear the buffer before reading.
            packetBuffer.clear()

            // Read from the VPN interface.
            val length = vpnInterface?.fileDescriptor?.let { datagramChannel.read(packetBuffer) } ?: -1
            if (length > 0) {
                // Process the packet.
                packetBuffer.flip()
                val destinationIp = getDestinationIp(packetBuffer)

                // Filter packets based on destination IP.
                if (shouldBlock(destinationIp)) {
                    // Log or handle blocked packets.
                    println("Blocked packet to IP: $destinationIp")
                } else {
                    // Forward the packet to the intended destination.
                    datagramChannel.write(packetBuffer)
                }
            }
        }

        // Close the VPN interface and channel when done.
        vpnInterface?.close()
        datagramChannel.close()
    }

