use App\Models\User;
use App\Models\Favorite;
use Illuminate\Support\Facades\Session;

class FavoritesManager
{
    protected $user;

    public function __construct(User $user = null)
    {
        $this->user = $user;
    }

    public function addFavorite($name)
    {
        if ($this->user) {
            // Add to database for logged-in users
            Favorite::create([
                'user_id' => $this->user->id,
                'name' => $name,
            ]);
        } else {
            // Add to session for guests
            $favorites = Session::get('favorites', []);
            $favorites[] = $name;
            Session::put('favorites', $favorites);
        }
    }

    public function removeFavorite($name)
    {
        if ($this->user) {
            // Remove from database for logged-in users
            Favorite::where('user_id', $this->user->id)
                ->where('name', $name)
                ->delete();
        } else {
            // Remove from session for guests
            $favorites = Session::get('favorites', []);
            if (($key = array_search($name, $favorites)) !== false) {
                unset($favorites[$key]);
            }
            Session::put('favorites', $favorites);
        }
    }

    public function getFavorites()
    {
        if ($this->user) {
            // Get from database for logged-in users
            return Favorite::where('user_id', $this->user->id)->pluck('name')->toArray();
        } else {
            // Get from session for guests
            return Session::get('favorites', []);
        }
    }
}
