<?php

namespace App\Http\Controllers;

use App\Favorites\FavoritesManager;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\Auth;

class FavoritesController extends Controller
{
    protected $favoritesManager;

    public function __construct()
    {
        $this->middleware(function ($request, $next) {
            $this->favoritesManager = new FavoritesManager(Auth::user());
            return $next($request);
        });
    }

    public function add(Request $request)
    {
        $request->validate([
            'name' => 'required|string|max:255',
        ]);

        $this->favoritesManager->addFavorite($request->input('name'));

        return response()->json(['status' => 'success']);
    }

    public function remove(Request $request)
    {
        $request->validate([
            'name' => 'required|string|max:255',
        ]);

        $this->favoritesManager->removeFavorite($request->input('name'));

        return response()->json(['status' => 'success']);
    }

    public function list()
    {
        $favorites = $this->favoritesManager->getFavorites();

        return response()->json(['favorites' => $favorites]);
    }
}
