#pragma HLS INTERFACE m_axi depth=784 port=input offset=slave
#pragma HLS INTERFACE m_axi depth=128*784 port=weights1 offset=slave
#pragma HLS INTERFACE m_axi depth=128 port=bias1 offset=slave
#pragma HLS INTERFACE m_axi depth=10*128 port=weights2 offset=slave
#pragma HLS INTERFACE m_axi depth=10 port=bias2 offset=slave
#pragma HLS INTERFACE m_axi depth=10 port=output offset=slave

    data_t hidden_layer[HIDDEN_LAYER_SIZE];
    data_t output_layer[OUTPUT_SIZE];

