Creating a Connect Four game involves designing a board, allowing two players to take turns dropping their respective pieces into columns, and checking for a win condition after each move. Below is a simple text-based implementation of Connect Four in Python:

```python
class ConnectFour:
    def __init__(self):
        self.rows = 6
        self.cols = 7
        self.board = [[' ' for _ in range(self.cols)] for _ in range(self.rows)]
        self.current_player = 'X'

    def print_board(self):
        for row in self.board:
            print('|'.join(row))
            print('-' * (self.cols * 2 - 1))
        print(' '.join(str(i) for i in range(self.cols)))

    def is_valid_move(self, col):
        return self.board[0][col] == ' '

    def get_next_open_row(self, col):
        for r in range(self.rows-1, -1, -1):
            if self.board[r][col] == ' ':
                return r
        return None

    def drop_piece(self, row, col):
        self.board[row][col] = self.current_player

    def switch_player(self):
        self.current_player = 'O' if self.current_player == 'X' else 'X'

    def winning_move(self, piece):
        # Check horizontal locations
        for c in range(self.cols - 3):
            for r in range(self.rows):
                if (self.board[r][c] == piece and self.board[r][c+1] == piece and
                    self.board[r][c+2] == piece and self.board[r][c+3] == piece):
                    return True

        # Check vertical locations
        for c in range(self.cols):
            for r in range(self.rows - 3):
                if (self.board[r][c] == piece and self.board[r+1][c] == piece and
                    self.board[r+2][c] == piece and self.board[r+3][c] == piece):
                    return True

        # Check positively sloped diagonals
        for c in range(self.cols - 3):
            for r in range(self.rows - 3):
                if (self.board[r][c] == piece and self.board[r+1][c+1] == piece and
                    self.board[r+2][c+2] == piece and self.board[r+3][c+3] == piece):
                    return True

        # Check negatively sloped diagonals
        for c in range(self.cols - 3):
            for r in range(3, self.rows):
                if (self.board[r][c] == piece and self.board[r-1][c+1] == piece and
                    self.board[r-2][c+2] == piece and self.board[r-3][c+3] == piece):
                    return True

        return False

    def play(self):
        game_over = False
        while not game_over:
            self.print_board()
            col = int(input(f"Player {self.current_player}, make your move (0-{self.cols - 1}): "))
            if not (0 <= col < self.cols) or not self.is_valid_move(col):
                print("Invalid move. Try again.")
                continue

            row = self.get_next_open_row(col)
            self.drop_piece(row, col)

            if self.winning_move(self.current_player):
                self.print_board()
                print(f"Player {self.current_player} wins!")
                game_over = True
            else:
                self.switch_player()

if __name__ == "__main__":
    game = ConnectFour()
    game.play()
```

### How the Game Works:
- The board is represented by a 6x7 grid.
- Players take turns to drop their pieces ('X' or 'O') into one of the columns.
- The game checks for a win condition after each move: four consecutive pieces of the same type horizontally, vertically, or diagonally.
- The game continues until a player wins or the board is full.

This implementation is console-based and assumes two human players. For a more advanced version, you could add features like AI opponents, a graphical interface, or network play.

