use std::fs::File;
use std::io::{self, BufRead};
use std::path::Path;
use std::process::Command;

// Function to check if a URL is a YouTube URL
fn is_youtube_url(url: &str) -> bool {
    url.contains("youtube.com") || url.contains("youtu.be")
}

// Function to download a YouTube URL using yt-dlp
fn download_youtube_url(url: &str) -> io::Result<()> {
    Command::new("yt-dlp")
        .arg(url)
        .status()
        .expect("Failed to execute yt-dlp");
    Ok(())
}

fn main() -> io::Result<()> {
    // Define the path to the file containing URLs
    let path = "urls.txt";

    // Open the file in read-only mode (ignoring errors)
    let file = File::open(&path)?;
    let reader = io::BufReader::new(file);

    // Iterate over each line in the file
    for line in reader.lines() {
        // Unwrap the line, or continue if there's an error
        if let Ok(url) = line {
            if is_youtube_url(&url) {
                println!("Downloading YouTube URL: {}", url);
                download_youtube_url(&url)?;
            } else {
                println!("Non-YouTube URL: {}", url);
            }
