using System;
using System.Net.Http;
using System.Security.Cryptography.X509Certificates;
using System.Threading.Tasks;

class Program
{
    static async Task Main(string[] args)
    {
        // Path to your client certificate
        string certPath = "path/to/your/certificate.pfx";
        // Password for your certificate
        string certPassword = "your_cert_password";

        // Load the client certificate
        var clientCertificate = new X509Certificate2(certPath, certPassword);

